import sys


def load(path):
    if not path:
        raise ValueError("path required")
    with open(path) as handle:
        return handle.read()


def parse(text):
    return text.split()


def run(argv):
    data = load(argv[1])
    return parse(data)


def main():
    print("result", run(sys.argv))

